Hello! Your setup is quite comprehensive, but I can suggest some improvements for production readiness. Here's an enhanced approach:

**1. Enhanced Middleware Structure**
```typescript
// middleware.ts
import createMiddleware from "next-intl/middleware";
import { type NextRequest, NextResponse } from "next/server";
import { routing } from "@/i18n/routing";
import { createServerClient } from "@supabase/ssr";
import { getPathname } from "@/i18n/navigation";

const handleI18nRouting = createMiddleware(routing);

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const subdomain = extractSubdomain(request);
  
  if (!subdomain) {
    return handleI18nRouting(request);
  }

  const response = handleI18nRouting(request);
  return await handleTenantRouting(request, response, subdomain);
}

async function handleTenantRouting(
  request: NextRequest, 
  response: NextResponse, 
  subdomain: string
) {
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll: () => request.cookies.getAll(),
        setAll: (cookiesToSet) => {
          cookiesToSet.forEach(({ name, value, options }) => {
            response.cookies.set(name, value, options);
          });
        },
      },
    }
  );

  const { data: tenant, error } = await supabase
    .from("tenants")
    .select("id, status")
    .eq("subdomain", subdomain)
    .eq("status", "active")
    .single();

  if (!tenant || error) {
    return new NextResponse("Tenant not found", { status: 404 });
  }

  const { data: { user } } = await supabase.auth.getUser();
  const isAuthPath = pathname.includes('/auth/');
  const isPublicPath = ['/login', '/signup', '/pricing'].some(path => 
    pathname.includes(path)
  );

  if (!user && !isPublicPath && !isAuthPath) {
    const loginUrl = new URL(`/login`, request.url);
    return NextResponse.redirect(loginUrl);
  }

  response.headers.set('x-tenant-id', tenant.id);
  response.headers.set('x-tenant-subdomain', subdomain);

  return response;
}
```

**2. Tenant-Aware Database Client**
```typescript
// lib/supabase/tenant-client.ts
import { createServerClient } from "@supabase/ssr";
import { headers } from "next/headers";

export async function createTenantClient() {
  const headersList = await headers();
  const tenantId = headersList.get('x-tenant-id');
  
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      global: {
        headers: {
          'X-Tenant-ID': tenantId || '',
        },
      },
    }
  );

  return supabase;
}
```

**3. Row Level Security (RLS) for Multi-tenancy**
```sql
ALTER TABLE projects ENABLE ROW LEVEL SECURITY;

CREATE POLICY "tenant_isolation" ON projects
FOR ALL USING (tenant_id = current_setting('app.current_tenant_id')::uuid);
```

**4. Production Security Considerations**
- Implement proper CORS settings for subdomains
- Use secure cookie settings with sameSite='lax'
- Add rate limiting per tenant
- Implement tenant-level query timeouts
- Add comprehensive logging and monitoring

**5. Vercel Configuration**
```json
// vercel.json
{
  "buildCommand": "npm run build",
  "outputDirectory": ".next",
  "functions": {
    "app/[locale]/(app)/[tenant]/**/*": {
      "maxDuration": 30
    }
  }
}
```

This approach ensures proper tenant isolation, security, and scalability for production use. The key is combining middleware-based routing with Supabase RLS for robust multi-tenancy.

