## Key Observations



### Hydration Behavior
- **Server-side**: Metadata renders correctly (no duplication)
- **Client-side**: React hydration duplicates metadata tags
- **Timing**: Occurs after client load
- **Scope**: Only affects product pages

## Rendering Strategy
**Hybrid Approach: Static Generation + Dynamic Fallback**

- **Pre-rendered**: Known products are built at build time (static)
- **On-demand**: Unknown/new products render server-side on first request
- **Cached**: Data fetching prevents duplicate API calls

## Page Structure
```typescript
// src/app/(main)/products/[handle]/page.tsx
import { Metadata } from "next"
import { notFound } from "next/navigation"
import { cache } from "react"
import { listProducts } from "@lib/data/products"
import { getRegion, listRegions, getRegionShippingOptions } from "@lib/data/regions"
import ProductTemplate from "@modules/products/templates"
import { generateProductMetadata } from "@lib/util/metadata-generator"

type Props = {
  params: Promise<{ countryCode: string; handle: string }>
}

// Cached function to fetch product data
const getProduct = cache(async (countryCode: string, handle: string) => {
  const region = await getRegion("gb")
  
  if (!region) {
    return null
  }

  const pricedProduct = await listProducts({
    countryCode: "gb",
    queryParams: { 
      handle,
      fields: "*variants.calculated_price,+variants.inventory_quantity,+metadata,+tags,+categories.id,+categories.name,+categories.handle,+categories.parent_category,+categories.parent_category.parent_category,+categories.metadata,+categories.parent_category.metadata,+categories.parent_category.id"
    },
  }).then(({ response }) => response.products[0])

  const shippingOptions = await getRegionShippingOptions(region.id)
  return { product: pricedProduct, region, shippingOptions }
})

// Generate metadata for product pages
export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { countryCode, handle } = await params
  
  try {
    const result = await getProduct(countryCode, handle)
    
    if (!result?.product) {
      return {
        title: "Product Not Found",
        description: "The requested product could not be found.",
      }
    }

    const { product } = result
    
    return generateProductMetadata({
      title: product.title,
      description: product.description || `Shop ${product.title} at Company Name.`,
      keywords: product.tags?.map(tag => tag.value) || [],
      canonical: `/products/${product.handle}`,
      ogImage: product.images?.[0]?.url,
      images: product.images?.map(img => img.url) || [],
      price: product.variants?.[0]?.calculated_price?.calculated_amount?.toString(),
      availability: product.variants?.[0]?.inventory_quantity && product.variants[0].inventory_quantity > 0 ? "in stock" : "out of stock",
      brand: (typeof product.metadata?.brand === 'string' ? product.metadata.brand : "Company Name"),
      category: product.categories?.[0]?.name || (typeof product.metadata?.category === 'string' ? product.metadata.category : "Products"),
    })
  } catch (error) {
    console.error("Error generating product metadata:", error)
    return {
      title: "Product",
      description: "Premium products at Company Name.",
    }
  }
}

// Static generation for known products
export async function generateStaticParams() {
  try {
    const countryCodes = await listRegions().then((regions) =>
      regions?.map((r) => r.countries?.map((c) => c.iso_2)).flat()
    )

    if (!countryCodes) {
      return []
    }

    const promises = countryCodes.map(async (country) => {
      const { response } = await listProducts({
        countryCode: country,
        queryParams: { limit: 100, fields: "handle" },
      })

      return {
        country,
        products: response.products,
      }
    })

    const countryProducts = await Promise.all(promises)

    return countryProducts
      .flatMap((countryData) =>
        countryData.products.map((product) => ({
          countryCode: countryData.country,
          handle: product.handle,
        }))
      )
      .filter((param) => param.handle)
  } catch (error) {
    console.error(`Failed to generate static paths for product pages: ${error instanceof Error ? error.message : "Unknown error"}.`)
    return []
  }
}

export default async function ProductPage(props: Props) {
  const params = await props.params
  const result = await getProduct(params.countryCode, params.handle)

  if (!result?.product || !result?.region) {
    notFound()
  }

  return (
    <ProductTemplate
      product={result.product}
      region={result.region}
      shippingOptions={result.shippingOptions}
      countryCode="gb"
    />
  )
}
