    // If AbortError from p-retry, it means permanent (e.g. private profile)
    console.error('Failed processing', vanityOrSteamId, err.message);
    return { success: false, error: err.message };
  }
}

async function main(users) {
  const limit = pLimit(CONCURRENCY);
  const tasks = users.map(u => limit(() => processUser(u.vanityOrId, u.dbId)));
  return Promise.all(tasks);
}

// run:
// await main([{vanityOrId: 'alice', dbId: 'user_alice'}, ...]);

```
**Other practical tips**

Never call the Steam API from client-side JS: your API key will leak and you’ll face CORS issues. Always do this from your server... :3

Monitor the key: Log the X-RateLimit-* headers if present (Steam may not send standard headers, but sometimes wrappers do). If you start seeing a lot of 429s, reduce concurrency further.

Respect private profiles: mark them in your DB so you don’t keep retrying forever.

Test with a single account: add lots of logging, then scale CONCURRENCY slowly from 1 → 2 → 5.

Backoff on 401: if the API gives 401 intermittently, ensure the same API_KEY is being used and not rotated; sometimes shared keys or environment issues cause sporadic 401. If it persists, rotate the key in Steam (or check if the key has been rate-limited/disabled).

Dedup logic: use a DB unique index on { userId: 1, appid: 1 } to prevent duplicates even if you accidentally try to insert twice.

