You’re very close. I think the remaining issue is that you’re mixing two accordion-control approaches.

`AccordionHeader` already has the toggle behavior built into React-Bootstrap, so you **_usually_** should not also put your own `onClick` on it unless you are intentionally controlling the Accordion yourself.

Try the simplest uncontrolled version first:

```jsx
<Accordion>
  {data.map((provider) => {
    const eventKey = String(provider.id);

    return (
      <AccordionItem key={eventKey} eventKey={eventKey}>
        <AccordionHeader as="h2">
          {provider.name} {provider.description}
        </AccordionHeader>

        <AccordionBody>
          BODY
        </AccordionBody>
      </AccordionItem>
    );
  })}
</Accordion>
```

So like...

* Keep `eventKey` on `AccordionItem`.
* Remove `eventKey` from `AccordionHeader`.
* Remove `eventKey` from `AccordionBody`.
* Remove the custom `onClick` for now.
* Remove the custom `open` / `selectedid` state unless you actually need to control the Accordion manually.

<details>
<summary>If you do want to track which item is open</summary>

Then use `Accordion`’s `onSelect` / `activeKey` instead of adding an `onClick` to each header:

```jsx
'use client';

import { useState } from 'react';
import {
  Accordion,
  AccordionItem,
  AccordionHeader,
  AccordionBody,
} from 'react-bootstrap';

function RAccordion({ data }) {
  const [activeKey, setActiveKey] = useState(null);

  return (
    <Accordion activeKey={activeKey} onSelect={(key) => setActiveKey(key)}>
      {data.map((provider) => {
        const eventKey = String(provider.id);

        return (
          <AccordionItem key={eventKey} eventKey={eventKey}>
            <AccordionHeader as="h2">
              {provider.name} {provider.description}
            </AccordionHeader>

            <AccordionBody>
              BODY
            </AccordionBody>
          </AccordionItem>
        );
      })}
    </Accordion>
  );
}

export default RAccordion;
```

</details>

